const $=id=>document.getElementById(id);const store={get(k,d=[]){try{return JSON.parse(localStorage.getItem('kx2_'+k))??d}catch{return d}},set(k,v){localStorage.setItem('kx2_'+k,JSON.stringify(v))}};let deferredPrompt=null,lastResult='',chatHistory=[];
const toolInfo={writer:['AI CREATION','AI Writer','Create clear, polished writing from a simple idea.'],image:['AI CREATION','Image Studio','Create a detailed visual prompt or generate an image when the image API is connected.'],video:['AI CREATION','Video Script Studio','Build engaging scripts for YouTube Shorts, Reels and explainers.'],social:['AI CREATION','Social Media Kit','Create hooks, captions, post ideas and hashtags.'],summarizer:['AI PRODUCTIVITY','Smart Summarizer','Turn long text into a short, useful summary.'],translator:['AI PRODUCTIVITY','Translator','Translate text while keeping its meaning and tone.'],study:['LEARNING','Study Tutor','Understand a topic with simple, step-by-step explanations.'],calculator:['EVERYDAY TOOLS','Smart Calculator','Calculate expressions safely in your browser.'],notes:['EVERYDAY TOOLS','Notes & Tasks','Save quick notes and organize your to-do list.'],invoice:['EVERYDAY TOOLS','Invoice Maker','Create a simple itemized bill and print it.']};
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2300)}
function view(v){document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));$('view-'+v).classList.add('active');document.querySelectorAll('.side-link').forEach(x=>x.classList.toggle('active',x.dataset.view===v));$('crumbName').textContent=v==='home'?'Overview':v==='ai'?'AI Assistant':v==='settings'?'Settings':toolInfo[v]?.[1]||'Workspace';$('sidebar').classList.remove('open');window.scrollTo(0,0)}
function tool(t){if(!toolInfo[t])return;view('tool');$('crumbName').textContent=toolInfo[t][1];$('toolCategory').textContent=toolInfo[t][0];$('toolTitle').textContent=toolInfo[t][1];$('toolDescription').textContent=toolInfo[t][2];buildTool(t);$('toolResult').innerHTML='<div class="empty-result"><span>✧</span><b>Your result will appear here</b><small>Enter your details and tap Generate.</small></div>';lastResult='';}
function buildTool(t){let f='';const field=(id,label,placeholder,textarea=false)=>'<div class="form-field"><label for="'+id+'">'+label+'</label>'+(textarea?'<textarea id="'+id+'" placeholder="'+placeholder+'"></textarea>':'<input id="'+id+'" placeholder="'+placeholder+'">')+'</div>';const select=(id,label,opts)=>'<div class="form-field"><label>'+label+'</label><select id="'+id+'">'+opts.map(o=>'<option>'+o+'</option>').join('')+'</select></div>';
if(t==='writer')f=select('tone','Writing style',['Friendly','Professional','Creative','Simple and clear'])+select('length','Length',['Short','Medium','Detailed'])+field('prompt','What should I write?','Describe your topic, audience and key points.',true)+genButton('Generate writing');
if(t==='image')f=select('imageStyle','Visual style',['Photorealistic','Cinematic','3D render','Minimal illustration','Anime-inspired','Product photography'])+field('prompt','Describe your image','Describe the subject, setting, lighting and mood.',true)+'<p class="form-hint">Creates a detailed image prompt. Actual image generation needs a connected image provider.</p>'+genButton('Generate image');
if(t==='video')f=select('platform','Platform',['YouTube Short','Instagram Reel','YouTube video'])+select('language','Language',['Hindi','Hinglish','English'])+select('duration','Duration',['15 seconds','30 seconds','45 seconds','60 seconds'])+field('prompt','Video topic','What should the video explain or show?',true)+genButton('Generate video script');
if(t==='social')f=select('platform','Platform',['YouTube','Instagram','Facebook','X'])+field('prompt','Topic or product','What is your post about?',true)+genButton('Create social kit');
if(t==='summarizer')f=select('length','Summary length',['Very short','Short','Detailed'])+field('prompt','Paste text to summarize','Paste your text here…',true)+genButton('Summarize');
if(t==='translator')f=select('target','Translate into',['Hindi','English','Hinglish','Spanish','French','German','Japanese'])+field('prompt','Text to translate','Paste text here…',true)+genButton('Translate');
if(t==='study')f=select('level','Explain for',['Beginner','Class 10','Class 11','Class 12','Advanced'])+select('language','Language',['Simple Hindi','Hinglish','English'])+field('prompt','What do you want to learn?','Enter a topic or question.',true)+genButton('Explain step by step');
if(t==='calculator')f='<div class="form-field"><label>Expression</label><input id="calcExpr" class="calc-input" placeholder="Example: (125 + 75) * 2"></div><button class="btn btn-primary" id="calcGo">Calculate</button><p class="form-hint">Supports +, −, ×, ÷, brackets, decimals and percentages.</p>';
if(t==='notes')f=field('noteTitle','Note title','Give your note a title')+field('noteBody','Your note','Write something to remember…',true)+'<button class="btn btn-primary" id="saveNote">Save note</button><hr><div id="notesList"></div><div class="form-field" style="margin-top:18px"><label>New task</label><input id="taskText" placeholder="Add a task"></div><button class="btn btn-ghost" id="addTask">Add task</button><div id="tasksList"></div>';
if(t==='invoice')f=field('businessName','Business name','Your shop or business')+field('customerName','Customer name','Customer')+'<div class="form-field"><label>Item name</label><input id="itemName" placeholder="Product or service"></div><div class="form-field"><label>Quantity</label><input id="itemQty" type="number" value="1"></div><div class="form-field"><label>Price per item (₹)</label><input id="itemPrice" type="number" placeholder="0"></div><button class="btn btn-primary" id="addInvoiceItem">Add item</button><div id="invoiceRows"></div><button class="btn btn-ghost" id="printInvoice" style="margin-top:12px">Print invoice</button>';
$('toolForm').innerHTML=f;
if(['writer','image','video','social','summarizer','translator','study'].includes(t))$('generateBtn').onclick=()=>runTool(t);
if(t==='calculator')$('calcGo').onclick=()=>{let s=$('calcExpr').value;if(!/^[0-9+*/().%\s-]+$/.test(s))return result('Only basic arithmetic characters are allowed.');try{result(String(Function('"use strict";return ('+s+')')()))}catch{result('Please check your expression.')}};
if(t==='notes'){renderNotes();$('saveNote').onclick=()=>{let a=store.get('notes');a.unshift({id:Date.now(),title:$('noteTitle').value||'Untitled',body:$('noteBody').value});store.set('notes',a);renderNotes();toast('Note saved')};$('addTask').onclick=()=>{let v=$('taskText').value.trim();if(!v)return;let a=store.get('tasks');a.push({id:Date.now(),text:v,done:false});store.set('tasks',a);$('taskText').value='';renderNotes()}}
if(t==='invoice')setupInvoice();
}
function genButton(label){return '<button class="btn btn-primary" id="generateBtn">'+label+' ✦</button><p class="form-hint">AI output is generated by your connected server. Never paste private passwords or sensitive information.</p>'}
async function runTool(t){let p=$('prompt')?.value.trim();if(!p)return toast('Please enter your topic or text first.');let instructions={writer:'Write a polished '+$('tone').value+' piece. Length: '+$('length').value+'. Include a useful title if appropriate.',image:'Create a high-quality image generation prompt in English. Visual style: '+$('imageStyle').value+'. Describe composition, lighting, camera and details. Do not generate an image; return only the prompt.',video:'Write a '+$('duration').value+' '+$('platform').value+' script in '+$('language').value+'. Start with a strong hook, use short spoken lines, suggest visuals and end with a memorable CTA.',social:'Create a complete '+$('platform').value+' social media kit: 5 hooks, one caption, CTA and relevant hashtags.',summarizer:'Summarize the supplied text. Length: '+$('length').value+'. Preserve key facts and do not invent details.',translator:'Translate the text into '+$('target').value+'. Preserve tone and formatting.',study:'Teach this for '+$('level').value+' in '+$('language').value+'. Explain the concept simply, then give an example and a short recap.'};await aiRequest(instructions[t]+'\n\nUser input:\n'+p,$('generateBtn'),t==='image'?'image':'text')}
function result(s){lastResult=s;$('toolResult').textContent=s}
async function aiRequest(message,button,mode='text'){button.disabled=true;button.textContent='Working…';$('toolResult').textContent='Kryptex AI is thinking…';try{let r=await fetch('./api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message,mode})});let d=await r.json();if(!r.ok)throw Error(d.error||'AI request failed');if(d.image){$('toolResult').innerHTML='<img alt="Generated result" style="max-width:100%;border-radius:10px" src="'+d.image+'">';lastResult=d.image}else result(d.reply||d.text||'No output received.')}catch(e){result('AI connection unavailable. '+e.message+'\n\nOpen Settings → Test AI connection. The backend must be deployed and have a valid provider key.')}finally{button.disabled=false;button.textContent=button.dataset.label||'Generate ✦'}}
async function chatSend(text){if(!text.trim())return;let log=$('chatLog');log.querySelector('.welcome-ai')?.remove();addBubble('user',text);$('chatInput').value='';let wait=addBubble('ai','Kryptex AI is thinking…');try{let r=await fetch('./api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:text,mode:'chat'})});let d=await r.json();if(!r.ok)throw Error(d.error||'AI request failed');wait.textContent=d.reply||d.text||'No response received.';chatHistory.push({role:'user',text},{role:'assistant',text:wait.textContent});}catch(e){wait.textContent='AI connection unavailable: '+e.message+' Open Settings and test the backend connection.'}log.scrollTop=log.scrollHeight}
function addBubble(role,text){let d=document.createElement('div');d.className='bubble '+role;d.textContent=text;$('chatLog').appendChild(d);$('chatLog').scrollTop=$('chatLog').scrollHeight;return d}
function renderNotes(){let n=store.get('notes'),t=store.get('tasks');if($('notesList'))$('notesList').innerHTML='<b>Saved notes</b>'+n.map(x=>'<div class="saved-item"><b>'+esc(x.title)+'</b><p>'+esc(x.body)+'</p><button class="small-btn" data-del-note="'+x.id+'">Delete</button></div>').join('');if($('tasksList'))$('tasksList').innerHTML='<b>Tasks</b>'+t.map(x=>'<div class="saved-item"><label><input type="checkbox" data-task="'+x.id+'" '+(x.done?'checked':'')+'> '+esc(x.text)+'</label><button class="small-btn" data-del-task="'+x.id+'">×</button></div>').join('');document.querySelectorAll('[data-del-note]').forEach(b=>b.onclick=()=>{store.set('notes',store.get('notes').filter(x=>x.id!=b.dataset.delNote));renderNotes()});document.querySelectorAll('[data-task]').forEach(b=>b.onchange=()=>{store.set('tasks',store.get('tasks').map(x=>x.id==b.dataset.task?{...x,done:b.checked}:x));renderNotes()});document.querySelectorAll('[data-del-task]').forEach(b=>b.onclick=()=>{store.set('tasks',store.get('tasks').filter(x=>x.id!=b.dataset.delTask));renderNotes()})}
let invoiceItems=[];function setupInvoice(){$('addInvoiceItem').onclick=()=>{let name=$('itemName').value.trim(),q=+$('itemQty').value,p=+$('itemPrice').value;if(!name||q<1||p<0||!Number.isFinite(p))return toast('Enter valid item details');invoiceItems.push({name,q,p});renderInvoice()};$('printInvoice').onclick=()=>{if(!invoiceItems.length)return toast('Add at least one item');let total=invoiceItems.reduce((s,x)=>s+x.q*x.p,0),w=window.open('','_blank');if(!w)return toast('Allow pop-ups to print');w.document.write('<h1>'+esc($('businessName').value||'Invoice')+'</h1><p>Customer: '+esc($('customerName').value)+'</p><table border="1" cellpadding="8"><tr><th>Item</th><th>Qty</th><th>Rate</th><th>Total</th></tr>'+invoiceItems.map(x=>'<tr><td>'+esc(x.name)+'</td><td>'+x.q+'</td><td>'+x.p+'</td><td>'+x.q*x.p+'</td></tr>').join('')+'</table><h3>Total: ₹'+total.toFixed(2)+'</h3>');w.document.close();w.print()}}
function renderInvoice(){let el=$('invoiceRows');el.innerHTML=invoiceItems.map((x,i)=>'<div class="saved-item">'+esc(x.name)+' · '+x.q+' × ₹'+x.p+' = ₹'+(x.q*x.p).toFixed(2)+' <button class="small-btn" data-inv="'+i+'">×</button></div>').join('')+'<b>Grand total: ₹'+invoiceItems.reduce((s,x)=>s+x.q*x.p,0).toFixed(2)+'</b>';document.querySelectorAll('[data-inv]').forEach(b=>b.onclick=()=>{invoiceItems.splice(+b.dataset.inv,1);renderInvoice()})}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
$('chatForm').onsubmit=e=>{e.preventDefault();chatSend($('chatInput').value)};$('chatInput').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('chatForm').requestSubmit()}};$('clearChat').onclick=()=>{$('chatLog').innerHTML='<div class="welcome-ai"><div class="ai-orb">✦</div><h2>What are we creating today?</h2><p>Start a fresh conversation.</p></div>';chatHistory=[]};document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>{view('ai');$('chatInput').value=b.dataset.prompt;$('chatForm').requestSubmit()});
document.addEventListener('click',e=>{let v=e.target.closest('[data-view]'),t=e.target.closest('[data-tool]');if(v){e.preventDefault();view(v.dataset.view)}if(t){e.preventDefault();tool(t.dataset.tool)}});
$('menuBtn').onclick=()=>$('sidebar').classList.toggle('open');$('themeBtn').onclick=()=>document.body.classList.toggle('light-mode');
$('copyResult').onclick=async()=>{if(!lastResult)return toast('Nothing to copy yet');try{await navigator.clipboard.writeText(lastResult);toast('Copied')}catch{toast('Copy not available in this browser')}};
$('downloadResult').onclick=()=>{if(!lastResult)return toast('Nothing to save yet');let a=document.createElement('a'),u=URL.createObjectURL(new Blob([lastResult],{type:'text/plain'}));a.href=u;a.download='kryptex-result.txt';a.click();URL.revokeObjectURL(u)};
async function testConnection(){let s=$('connectionStatus');s.className='connection-status';s.innerHTML='<i></i><span>Checking secure AI backend…</span>';try{let r=await fetch('./api/ai',{method:'GET'});let d=await r.json();if(r.ok){s.classList.add('ok');s.innerHTML='<i></i><span>Backend online · '+(d.provider||'AI provider')+'</span>'}else throw Error(d.error||'Not configured')}catch(e){s.classList.add('bad');s.innerHTML='<i></i><span>Backend not ready · '+esc(e.message)+'</span>'}}
$('testConnection').onclick=testConnection;$('exportBackup').onclick=()=>{let data={notes:store.get('notes'),tasks:store.get('tasks'),exportedAt:new Date().toISOString()};let a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.href=u;a.download='kryptex-backup.json';a.click();URL.revokeObjectURL(u)};$('clearLocal').onclick=()=>{if(confirm('Clear all notes and tasks saved on this device?')){localStorage.removeItem('kx2_notes');localStorage.removeItem('kx2_tasks');toast('Local data cleared')}};$('installFromSettings').onclick=installApp;
function installApp(){if(deferredPrompt){deferredPrompt.prompt();deferredPrompt=null}else toast('Open browser menu and choose “Add to Home screen”.')}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredPrompt=e;$('installBtn').hidden=false});$('installBtn').onclick=installApp;if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));testConnection();

