async function requestAI(prompt,button){button.disabled=true;button.textContent='Generating…';document.getElementById('toolResult').textContent='Kryptex AI is working…';try{const r=await fetch('./api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:prompt,mode:'chat'})});const d=await r.json();if(!r.ok)throw Error(d.error||'AI backend unavailable');document.getElementById('toolResult').textContent=d.reply||d.text||'No result returned.';window.kxLastResult=document.getElementById('toolResult').textContent}catch(e){document.getElementById('toolResult').textContent='AI service is not connected yet: '+e.message+'\n\nThis tool needs a configured and deployed backend.'}finally{button.disabled=false;button.textContent='Generate with Kryptex AI ✦'}}
function localToolAction(id){const el=x=>document.getElementById(x);let out='';
if(id==='password'){const n=Math.max(8,Math.min(64,Number(el('passLen').value)||18)),chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%&*_-+=';const a=new Uint32Array(n);crypto.getRandomValues(a);out=Array.from(a,x=>chars[x%chars.length]).join('');}
if(id==='compress'||id==='passport'){const file=el('assetFile')?.files[0];if(!file)return toast('Choose an image first');if(!file.type.startsWith('image/'))return toast('Please choose an image file');const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{const side=Math.min(img.width,img.height),canvas=document.createElement('canvas');if(id==='passport'){canvas.width=600;canvas.height=600;const ctx=canvas.getContext('2d');ctx.drawImage(img,(img.width-side)/2,(img.height-side)/2,side,side,0,0,600,600)}else{const scale=Math.min(1,1600/Math.max(img.width,img.height));canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height)}canvas.toBlob(blob=>{URL.revokeObjectURL(url);if(!blob)return toast('Could not process this image');const outUrl=URL.createObjectURL(blob),a=document.createElement('a');a.href=outUrl;a.download=id==='passport'?'kryptex-square-photo.jpg':'kryptex-compressed.jpg';a.click();setTimeout(()=>URL.revokeObjectURL(outUrl),3000);el('toolResult').innerHTML='<p>Image ready: '+canvas.width+' × '+canvas.height+' px</p><p>Original: '+(file.size/1024).toFixed(1)+' KB · Output: '+(blob.size/1024).toFixed(1)+' KB</p><img alt="Processed image preview" style="max-width:100%;border-radius:12px" src="'+outUrl+'">';window.kxLastResult='Image processed and downloaded.'},'image/jpeg',id==='compress'?Number(el('imageQuality').value)/100:.92)};img.onerror=()=>{URL.revokeObjectURL(url);toast('Could not read this image')};img.src=url;return}
if(id==='qr'){const v=el('catalogInput').value.trim();if(!v)return toast('Enter text or a URL');const url='https://quickchart.io/qr?size=240&text='+encodeURIComponent(v);el('toolResult').innerHTML='<img alt="Generated QR code" src="'+url+'" style="max-width:240px;background:white;padding:12px;border-radius:12px"><p>QR code for: '+escapeHTML(v)+'</p>';return}
if(id==='calculators'){const type=el('calcType').value,a=el('calcA').value,b=Number(el('calcB').value),c=Number(el('calcC').value);if(type==='Age'){const d=new Date(a);if(isNaN(d))return toast('Enter date of birth');let age=new Date().getFullYear()-d.getFullYear();const now=new Date();if(now<new Date(now.getFullYear(),d.getMonth(),d.getDate()))age--;out='Approximate age: '+age+' years.'}if(type==='BMI'){const kg=Number(a),m=b/100;if(!(kg>0&&m>0))return toast('Enter valid weight and height');out='BMI: '+(kg/(m*m)).toFixed(1)+'. BMI is only a rough screening measure and does not diagnose health.'}if(type==='EMI'){const p=Number(a),r=b/1200,n=c*12;if(!(p>0&&r>=0&&n>0))return toast('Enter valid loan, annual interest and years');const emi=r===0?p/n:p*r*Math.pow(1+r,n)/(Math.pow(1+r,n)-1);out='Estimated monthly EMI: ₹'+emi.toFixed(2)+'\nTotal repayment: ₹'+(emi*n).toFixed(2)+'\nInterest: ₹'+(emi*n-p).toFixed(2)}}
if(id==='unit'){const v=Number(el('unitValue').value),t=el('unitType').value;const f={'Kilometres to miles':v=>v*.621371,'Miles to kilometres':v=>v/ .621371,'Kilograms to pounds':v=>v*2.20462,'Pounds to kilograms':v=>v/2.20462,'Celsius to Fahrenheit':v=>v*9/5+32,'Fahrenheit to Celsius':v=>(v-32)*5/9};out=v+' → '+f[t](v).toFixed(3)+' ('+t+')'}
if(id==='date'){const a=new Date(el('dateA').value),b=new Date(el('dateB').value);if(isNaN(a)||isNaN(b))return toast('Choose both dates');out='Difference: '+Math.abs(Math.round((b-a)/86400000))+' days.'}
if(id==='textcase'){const s=el('catalogInput').value,mode=el('caseMode')?.value||'Sentence case';out=mode==='UPPERCASE'?s.toUpperCase():mode==='lowercase'?s.toLowerCase():mode==='Title Case'?s.toLowerCase().replace(/\b[a-z]/g,c=>c.toUpperCase()):s.charAt(0).toUpperCase()+s.slice(1).toLowerCase();}
if(id==='wordcount'){const s=el('catalogInput').value;out='Words: '+(s.trim()?s.trim().split(/\s+/).length:0)+'\nCharacters: '+s.length+'\nCharacters (without spaces): '+s.replace(/\s/g,'').length+'\nEstimated reading time: '+Math.ceil(s.trim().split(/\s+/).filter(Boolean).length/200)+' min'}
if(id==='color'){const hex=el('baseColor').value;const rgb=hex.match(/[a-f\d]{2}/gi).map(x=>parseInt(x,16));const shades=[-.35,-.18,0,.18,.35].map(f=>'#'+rgb.map(c=>Math.max(0,Math.min(255,Math.round(f<0?c*(1+f):c+(255-c)*f))).toString(16).padStart(2,'0')).join(''));out='Palette: '+shades.join('  ');el('toolResult').innerHTML='<div class="palette-row">'+shades.map(x=>'<div style="background:'+x+'"><span>'+x+'</span></div>').join('')+'</div>';return}
if(id==='markdown'){const s=el('catalogInput').value;el('toolResult').innerHTML='<div class="markdown-preview">'+escapeHTML(s).replace(/^### (.*)$/gm,'<h3>$1</h3>').replace(/^## (.*)$/gm,'<h2>$1</h2>').replace(/^# (.*)$/gm,'<h1>$1</h1>').replace(/\*\*(.*?)\*\*/g,'<b>$1</b>').replace(/\n/g,'<br>')+'</div>';return}
if(id==='csv'){const file=el('csvFile').files[0];if(!file)return toast('Choose a CSV file');const reader=new FileReader();reader.onload=()=>{const rows=String(reader.result).split(/\r?\n/).filter(Boolean).slice(0,101).map(r=>r.split(',').map(x=>x.replace(/^"|"$/g,'')));el('toolResult').innerHTML='<div class="table-scroll"><table class="csv-table">'+rows.map((r,i)=>'<tr>'+r.map(c=>i===0?'<th>'+escapeHTML(c)+'</th>':'<td>'+escapeHTML(c)+'</td>').join('')+'</tr>').join('')+'</table></div><small>Preview limited to first 100 rows; simple CSV parsing.</small>'};reader.readAsText(file);return}
if(id==='json'){const s=el('catalogInput').value;if(el('jsonMode').value==='HTML to printable PDF'){const w=window.open('','_blank');if(!w)return toast('Allow pop-ups to print');w.document.write(s);w.document.close();w.print();out='Opened printable HTML preview. Choose Save as PDF in the print dialog.'}else{try{out=JSON.stringify(JSON.parse(s),null,2)}catch(e){out='Invalid JSON: '+e.message}}}
if(out){el('toolResult').textContent=out;window.kxLastResult=out}}
function setupTimer(seconds){let left=seconds,interval=null;const display=document.getElementById('timerDisplay');const draw=()=>display.textContent=String(Math.floor(left/60)).padStart(2,'0')+':'+String(left%60).padStart(2,'0');document.getElementById('timerStart').onclick=()=>{if(interval)return;interval=setInterval(()=>{left--;draw();if(left<=0){clearInterval(interval);interval=null;toast('Timer complete!')}},1000)};document.getElementById('timerReset').onclick=()=>{clearInterval(interval);interval=null;left=seconds;draw()}}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function openGame(id){currentGame=id;clearInterval(gameTimer);if(window.kxGameKeyHandler){document.removeEventListener('keydown',window.kxGameKeyHandler);window.kxGameKeyHandler=null}const stage=document.getElementById('gameStage');stage.innerHTML='<div class="game-stage-head"><div><span class="eyebrow">KRYPTEX ARCADE</span><h2>'+gameCatalog.find(x=>x[0]===id)[1]+'</h2></div><button class="small-btn" id="closeGame">Close ×</button></div><div id="gameBoard" class="game-board"></div>';document.getElementById('closeGame').onclick=()=>{stage.innerHTML='<div class="empty-result"><span>🎮</span><b>Choose a game to play</b><small>Your game will open here.</small></div>';clearInterval(gameTimer);if(window.kxGameKeyHandler){document.removeEventListener('keydown',window.kxGameKeyHandler);window.kxGameKeyHandler=null}};const b=document.getElementById('gameBoard');clearInterval(gameTimer);gameState={};if(id==='tictactoe')gameTic(b);if(id==='mathgame')gameMath(b);if(id==='wordle')gameWord(b);if(id==='sudoku')gameSudoku(b);if(id==='memory')gameMemory(b);if(id==='typing')gameTyping(b);if(id==='quiz')gameQuiz(b);if(id==='chess')gameChess(b);if(id==='2048')game2048(b);if(id==='snake')gameSnake(b)}
function gameTic(b){let board=Array(9).fill(''),turn='X',over=false;function win(a,p){return [[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]].some(l=>l.every(i=>a[i]===p))}function score(a,p){if(win(a,'O'))return 10;if(win(a,'X'))return -10;if(a.every(Boolean))return 0;let best=p==='O'?-99:99;for(let i=0;i<9;i++)if(!a[i]){a[i]=p;let s=score(a,p==='O'?'X':'O');a[i]='';best=p==='O'?Math.max(best,s):Math.min(best,s)}return best}function ai(){let best=-99,move=-1;for(let i=0;i<9;i++)if(!board[i]){board[i]='O';let s=score(board,'X');board[i]='';if(s>best){best=s;move=i}}if(move>=0)board[move]='O';turn='X';draw()}function draw(){b.innerHTML='<p>You are X · Kryptex AI is O</p><div class="tic-grid">'+board.map((x,i)=>'<button data-cell="'+i+'">'+x+'</button>').join('')+'</div><p>'+ (over?'Game over':turn==='X'?'Your turn':'AI turn')+'</p><button class="btn btn-ghost" id="restartGame">Play again</button>';b.querySelectorAll('[data-cell]').forEach(x=>x.onclick=()=>{let i=+x.dataset.cell;if(over||board[i]||turn!=='X')return;board[i]='X';if(win(board,'X')){over=true;draw();return}if(board.every(Boolean)){over=true;draw();return}turn='O';draw();setTimeout(()=>{ai();if(win(board,'O')||board.every(Boolean))over=true;draw()},250)});b.querySelector('#restartGame').onclick=()=>gameTic(b)}draw()}
function gameMath(b){let score=0,left=60,a=0,op='',c=0,run=true;function q(){a=2+Math.floor(Math.random()*18);c=2+Math.floor(Math.random()*12);op=['+','−','×'][Math.floor(Math.random()*3)];b.querySelector('#mathQ').textContent=a+' '+op+' '+c+' = ?';b.querySelector('#mathAnswer').value='';b.querySelector('#mathAnswer').focus()}b.innerHTML='<div class="game-stat">Time <b id="mathTime">60</b>s · Score <b id="mathScore">0</b></div><h2 id="mathQ"></h2><input id="mathAnswer" type="number" placeholder="Your answer"><button class="btn btn-primary" id="mathSubmit">Submit</button>';q();b.querySelector('#mathSubmit').onclick=()=>{const correct=op==='+'?a+c:op==='−'?a-c:a*c;if(Number(b.querySelector('#mathAnswer').value)===correct){score++;b.querySelector('#mathScore').textContent=score}q()};gameTimer=setInterval(()=>{left--;b.querySelector('#mathTime').textContent=left;if(left<=0){clearInterval(gameTimer);b.insertAdjacentHTML('beforeend','<h3>Time up! Your score: '+score+'</h3>')}},1000)}
function gameWord(b){const words=['PLANT','BRAVE','CRANE','LIGHT','SHARE','SMILE','BRAIN','CLOUD','STONE','FRAME'];const answer=words[Math.floor((Date.now()/86400000)%words.length)];let tries=[];b.innerHTML='<p>Guess the 5-letter word in 6 tries. 🟩 right spot · 🟨 in word</p><div id="wordRows"></div><input id="wordGuess" maxlength="5" placeholder="5-letter word"><button class="btn btn-primary" id="wordTry">Check</button>';const draw=()=>{b.querySelector('#wordRows').innerHTML=tries.map(g=>'<div class="word-row">'+g.split('').map((c,i)=>'<span class="'+(c===answer[i]?'hit':answer.includes(c)?'near':'miss')+'">'+c+'</span>').join('')+'</div>').join('')};b.querySelector('#wordTry').onclick=()=>{const g=b.querySelector('#wordGuess').value.toUpperCase();if(!/^[A-Z]{5}$/.test(g))return toast('Enter 5 letters');if(tries.includes(g))return toast('You already tried that word');if(tries.length>=6||tries.includes(answer))return;tries.push(g);draw();b.querySelector('#wordGuess').value='';if(g===answer||tries.length>=6)b.insertAdjacentHTML('beforeend','<h3>'+(g===answer?'You got it!':'Word: '+answer)+'</h3>')}}
function gameSudoku(b){const puzzle='530070000600195000098000060800060003400803001700020006060000280000419005000080079'.split('').map(Number);let cells=[...puzzle];function valid(a,r,c,n){for(let i=0;i<9;i++)if(a[r*9+i]===n||a[i*9+c]===n)return false;let br=Math.floor(r/3)*3,bc=Math.floor(c/3)*3;for(let y=0;y<3;y++)for(let x=0;x<3;x++)if(a[(br+y)*9+bc+x]===n)return false;return true}function solve(a){let i=a.indexOf(0);if(i<0)return true;let r=Math.floor(i/9),c=i%9;for(let n=1;n<=9;n++)if(valid(a,r,c,n)){a[i]=n;if(solve(a))return true;a[i]=0}return false}function draw(){b.innerHTML='<p>Fill empty cells (0–9). Tap Solve to complete the puzzle.</p><div class="sudoku-grid">'+cells.map((v,i)=>'<input data-sud="'+i+'" maxlength="1" inputmode="numeric" value="'+(v||'')+'" '+(puzzle[i]?'readonly':'')+'>').join('')+'</div><button class="btn btn-primary" id="sudSolve">Solve puzzle</button> <button class="btn btn-ghost" id="sudReset">Reset</button>';b.querySelectorAll('[data-sud]').forEach(x=>x.oninput=()=>{cells[+x.dataset.sud]=Number(x.value)||0});b.querySelector('#sudSolve').onclick=()=>{let a=[...cells];if(solve(a)){cells=a;draw()}else toast('Could not solve this grid')};b.querySelector('#sudReset').onclick=()=>{cells=[...puzzle];draw()}}draw()}
function gameMemory(b){let vals=['🚀','🎧','🌈','⚽','🍀','🎮','🚀','🎧','🌈','⚽','🍀','🎮'].sort(()=>Math.random()-.5),open=[],matched=[];function draw(){b.innerHTML='<p>Find all matching pairs.</p><div class="memory-grid">'+vals.map((v,i)=>'<button data-mem="'+i+'">'+(matched.includes(i)||open.includes(i)?v:'?')+'</button>').join('')+'</div><p>Pairs: '+matched.length/2+' / 6</p>';b.querySelectorAll('[data-mem]').forEach(x=>x.onclick=()=>{let i=+x.dataset.mem;if(open.includes(i)||matched.includes(i)||open.length===2)return;open.push(i);draw();if(open.length===2){if(vals[open[0]]===vals[open[1]]){matched.push(...open);open=[];draw()}else setTimeout(()=>{open=[];draw()},700)}})}draw()}
function gameTyping(b){const lines=['Curiosity turns ordinary moments into discoveries.','Practice makes progress, one small step at a time.','Technology can make learning more creative and fun.'];const text=lines[Math.floor(Math.random()*lines.length)];b.innerHTML='<p>Type the sentence below as quickly and accurately as possible.</p><blockquote>'+text+'</blockquote><textarea id="typeInput" rows="3" placeholder="Start typing…"></textarea><p id="typeStats">WPM: 0 · Accuracy: 100%</p>';let start=0;b.querySelector('#typeInput').oninput=e=>{if(!start)start=Date.now();let v=e.target.value,correct=0;for(let i=0;i<v.length;i++)if(v[i]===text[i])correct++;let mins=(Date.now()-start)/60000,wpm=Math.round((v.trim().split(/\s+/).filter(Boolean).length||0)/Math.max(mins,.01));b.querySelector('#typeStats').textContent='WPM: '+wpm+' · Accuracy: '+Math.round(correct/Math.max(v.length,1)*100)+'%'+(v===text?' · Finished!':'')}}
function gameQuiz(b){const qs=[['Which planet is known as the Red Planet?',['Mars','Venus','Jupiter'],0],['What is the largest ocean?',['Atlantic','Pacific','Indian'],1],['Which gas do plants absorb?',['Oxygen','Nitrogen','Carbon dioxide'],2],['How many sides has a hexagon?',['5','6','8'],1],['What is H₂O commonly called?',['Salt','Water','Hydrogen'],1]];let i=0,s=0;function draw(){if(i>=qs.length){b.innerHTML='<h2>Quiz complete!</h2><h3>Your score: '+s+'/'+qs.length+'</h3><button class="btn btn-primary" id="quizAgain">Play again</button>';b.querySelector('#quizAgain').onclick=()=>{i=0;s=0;draw()};return}let q=qs[i];b.innerHTML='<p>Question '+(i+1)+' / '+qs.length+' · Score '+s+'</p><h2>'+q[0]+'</h2>'+q[1].map((x,j)=>'<button class="quiz-option" data-ans="'+j+'">'+x+'</button>').join('');b.querySelectorAll('[data-ans]').forEach(x=>x.onclick=()=>{if(+x.dataset.ans===q[2])s++;i++;draw()})}draw()}
function gameChess(b){let board=['♜','♞','♝','♛','♚','♝','♞','♜','♟','♟','♟','♟','♟','♟','♟','♟','','','','','','','','','','','','','','','','','','','','','','','','','','','','','','','','','','','','','','','','','','♙','♙','♙','♙','♙','♙','♙','♙','♖','♘','♗','♕','♔','♗','♘','♖'];let selected=null;b.innerHTML='<p>Simple demo board: select one of your white pieces, then choose a destination square. Basic move interaction only.</p><div class="chess-grid">'+board.map((p,i)=>'<button data-chess="'+i+'">'+p+'</button>').join('')+'</div><button class="btn btn-ghost" id="chessReset">Reset board</button>';function draw(){b.querySelectorAll('[data-chess]').forEach(x=>{x.classList.toggle('selected',+x.dataset.chess===selected);x.onclick=()=>{let i=+x.dataset.chess;if(selected===null){if(board[i]&&'♙♖♘♗♕♔'.includes(board[i]))selected=i}else{board[i]=board[selected];board[selected]='';selected=null;let ai=board.findIndex((v,j)=>v&&'♟♜♞♝♛♚'.includes(v)&&!board[j+8]);if(ai<0)ai=board.findIndex(v=>v==='♟');if(ai>=0){let dest=Math.min(63,ai+8);if(!board[dest]){board[dest]=board[ai];board[ai]=''}}}b.querySelectorAll('[data-chess]').forEach(z=>z.textContent=board[+z.dataset.chess]);draw()}})}draw();b.querySelector('#chessReset').onclick=()=>gameChess(b)}
function game2048(b){let a=Array(16).fill(0);a[Math.floor(Math.random()*16)]=2;function add(){let e=a.map((v,i)=>v?null:i).filter(x=>x!==null);if(e.length)a[e[Math.floor(Math.random()*e.length)]]=Math.random()<.9?2:4}function move(dir){let changed=false;for(let k=0;k<4;k++){let ids=Array.from({length:4},(_,i)=>dir==='left'?k*4+i:dir==='right'?k*4+3-i:dir==='up'?i*4+k:(3-i)*4+k);let vals=ids.map(i=>a[i]).filter(Boolean);for(let j=0;j<vals.length-1;j++)if(vals[j]===vals[j+1]){vals[j]*=2;vals.splice(j+1,1)}while(vals.length<4)vals.push(0);ids.forEach((id,j)=>{if(a[id]!==vals[j])changed=true;a[id]=vals[j]})}if(changed)add();draw()}function draw(){b.innerHTML='<p>Use arrow keys or buttons. Combine equal numbers to reach 2048.</p><div class="tile-grid">'+a.map(x=>'<div class="tile t'+x+'">'+(x||'')+'</div>').join('')+'</div><div class="direction-pad"><button data-dir="up">↑</button><button data-dir="left">←</button><button data-dir="down">↓</button><button data-dir="right">→</button></div><button class="btn btn-ghost" id="reset2048">Restart</button>';b.querySelectorAll('[data-dir]').forEach(x=>x.onclick=()=>move(x.dataset.dir));b.querySelector('#reset2048').onclick=()=>game2048(b)}function key(e){if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();move({ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down'}[e.key])}}if(window.kxGameKeyHandler)document.removeEventListener('keydown',window.kxGameKeyHandler);window.kxGameKeyHandler=e=>{if(currentGame!=='2048'||!document.getElementById('gameBoard')?.contains(b))return;key(e)};document.addEventListener('keydown',window.kxGameKeyHandler);draw()}
function gameSnake(b){clearInterval(gameTimer);if(window.kxGameKeyHandler){document.removeEventListener('keydown',window.kxGameKeyHandler);window.kxGameKeyHandler=null}b.innerHTML='<p>Use arrow keys or the buttons to move. Eat the dot and avoid the wall.</p><canvas id="snakeCanvas" width="300" height="300" class="snake-canvas"></canvas><div class="direction-pad"><button data-dir="up">↑</button><button data-dir="left">←</button><button data-dir="down">↓</button><button data-dir="right">→</button></div><p id="snakeScore">Score: 0</p><button class="btn btn-ghost" id="snakeRestart">Restart</button>';const c=b.querySelector('canvas'),ctx=c.getContext('2d');let snake=[{x:7,y:7},{x:6,y:7}],food={x:12,y:8},dir={x:1,y:0},score=0;function tick(){let h={x:snake[0].x+dir.x,y:snake[0].y+dir.y};if(h.x<0||h.y<0||h.x>=15||h.y>=15||snake.some(p=>p.x===h.x&&p.y===h.y)){clearInterval(gameTimer);ctx.fillStyle='#fff';ctx.font='20px sans-serif';ctx.fillText('Game over',100,150);return}snake.unshift(h);if(h.x===food.x&&h.y===food.y){score++;food={x:Math.floor(Math.random()*15),y:Math.floor(Math.random()*15)};b.querySelector('#snakeScore').textContent='Score: '+score}else snake.pop();ctx.clearRect(0,0,300,300);ctx.fillStyle='#f59e0b';ctx.fillRect(food.x*20,food.y*20,18,18);ctx.fillStyle='#8b5cf6';snake.forEach(p=>ctx.fillRect(p.x*20,p.y*20,18,18))}function set(d){const map={up:{x:0,y:-1},down:{x:0,y:1},left:{x:-1,y:0},right:{x:1,y:0}};let n=map[d];if(n.x!==-dir.x||n.y!==-dir.y)dir=n}b.querySelectorAll('[data-dir]').forEach(x=>x.onclick=()=>set(x.dataset.dir));const key=e=>{const m={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right'};if(m[e.key])set(m[e.key])};if(window.kxGameKeyHandler)document.removeEventListener('keydown',window.kxGameKeyHandler);window.kxGameKeyHandler=e=>{if(currentGame!=='snake'||!document.getElementById('gameBoard')?.contains(b))return;key(e)};document.addEventListener('keydown',window.kxGameKeyHandler);gameTimer=setInterval(tick,160);b.querySelector('#snakeRestart').onclick=()=>gameSnake(b)}
document.addEventListener('click',e=>{const t=e.target.closest('[data-open-tool]');if(t)openCatalogTool(t.dataset.openTool);const g=e.target.closest('[data-open-game]');if(g)openGame(g.dataset.openGame);const f=e.target.closest('[data-filter]');if(f){activeFilter=f.dataset.filter;document.querySelectorAll('.filter-chip').forEach(x=>x.classList.toggle('active',x===f));renderCatalog()}});
document.getElementById('toolSearch')?.addEventListener('input',renderCatalog);
document.addEventListener('click',e=>{const v=e.target.closest('[data-view]');if(v&&['catalog','games'].includes(v.dataset.view)){document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));document.getElementById('view-'+v.dataset.view).classList.add('active');document.getElementById('crumbName').textContent=v.dataset.view==='catalog'?'Open All Tools':'Game Zone';document.getElementById('sidebar').classList.remove('open');window.scrollTo(0,0)}});
renderCatalog();renderGames();

const originalSnakeGame=gameSnake;
gameSnake=function(b){originalSnakeGame(b);const btn=document.createElement('button');btn.className='btn btn-ghost';btn.textContent='🎲 Switch to 2-player Ludo';btn.onclick=()=>gameLudo(b);b.insertBefore(btn,b.firstChild)};
function gameLudo(b){let pos=[0,0],turn=0,finished=false;function draw(dice=null){b.innerHTML='<p>Two-player mini Ludo race · Roll a 6 to leave base · First to 30 spaces wins.</p><div class="game-stat">🔵 Player 1: <b>'+pos[0]+'</b> / 30 &nbsp; 🔴 Player 2: <b>'+pos[1]+'</b> / 30</div><div class="ludo-track">'+Array.from({length:31},(_,i)=>'<span class="'+(pos[0]===i?'p1 ':'')+(pos[1]===i?'p2 ':'')+'">'+(i===0?'🏁':i===30?'🏆':i)+'</span>').join('')+'</div><h3>'+(finished?'Race finished!':('Player '+(turn+1)+' turn'))+'</h3>'+(dice===null?'':'<p>Dice: '+dice+'</p>')+'<button class="btn btn-primary" id="ludoRoll" '+(finished?'disabled':'')+'>Roll dice 🎲</button> <button class="btn btn-ghost" id="ludoReset">Restart</button>';b.querySelector('#ludoRoll').onclick=()=>{let n=1+Math.floor(Math.random()*6);if(pos[turn]>0||n===6)pos[turn]=Math.min(30,pos[turn]+n);if(pos[turn]>=30)finished=true;else turn=1-turn;draw(n)};b.querySelector('#ludoReset').onclick=()=>{pos=[0,0];turn=0;finished=false;draw()}}draw()}
